// Backup lógico cifrado e teste de restauração em banco separado.
//
//   npx tsx scripts/backup.ts backup                 cria .backups/<data>/
//   npx tsx scripts/backup.ts restaurar <pasta>      restaura em alta_clara_restauracao e compara
//   npx tsx scripts/backup.ts teste                  faz os dois e grava a evidência
//
// Formato: COPY ... (FORMAT binary) de cada tabela, num snapshot consistente
// (REPEATABLE READ, somente leitura), cada arquivo cifrado com AES-256-GCM.
// O esquema vem das migrações versionadas (drizzle/), não do backup.
// Chave: ALTA_BACKUP_KEY (32 bytes base64url) no .env.local — guarde-a
// separada das cópias; sem ela o backup não pode ser lido.
import { createCipheriv, createDecipheriv, createHash, randomBytes } from "node:crypto";
import { appendFileSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { pipeline } from "node:stream/promises";
import { Readable } from "node:stream";
import { config } from "dotenv";
import pg from "pg";
import { from as copyFrom, to as copyTo } from "pg-copy-streams";
import { migrarBanco } from "../src/server/db/migrar";

config({ path: ".env.local", override: true });

const BANCO_RESTAURACAO = "alta_clara_restauracao";

function chave(): Buffer {
  let k = process.env.ALTA_BACKUP_KEY;
  if (!k) {
    k = randomBytes(32).toString("base64url");
    appendFileSync(".env.local", `\n# Chave dos backups (gerada por scripts/backup.ts). Guarde fora das cópias.\nALTA_BACKUP_KEY=${k}\n`);
    process.env.ALTA_BACKUP_KEY = k;
    console.log("ALTA_BACKUP_KEY gerada e salva em .env.local.");
  }
  return Buffer.from(k, "base64url");
}

function cifrar(dados: Buffer, k: Buffer) {
  const iv = randomBytes(12);
  const c = createCipheriv("aes-256-gcm", k, iv);
  const corpo = Buffer.concat([c.update(dados), c.final()]);
  return Buffer.concat([iv, c.getAuthTag(), corpo]);
}

function decifrar(dados: Buffer, k: Buffer) {
  const d = createDecipheriv("aes-256-gcm", k, dados.subarray(0, 12));
  d.setAuthTag(dados.subarray(12, 28));
  return Buffer.concat([d.update(dados.subarray(28)), d.final()]);
}

const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");

/** Tabelas do esquema público. A restauração carrega com as FKs suspensas e confere tudo ao final. */
async function tabelasOrdenadas(c: pg.ClientBase): Promise<string[]> {
  const { rows } = await c.query<{ t: string }>("select tablename as t from pg_tables where schemaname = 'public' order by tablename");
  return rows.map((r) => r.t);
}

async function lerTudo(stream: NodeJS.ReadableStream) {
  const partes: Buffer[] = [];
  for await (const p of stream) partes.push(p as Buffer);
  return Buffer.concat(partes);
}

export async function fazerBackup(urlOwner: string) {
  const k = chave();
  const pasta = path.join(".backups", new Date().toISOString().replace(/[:.]/g, "-"));
  mkdirSync(pasta, { recursive: true });
  const c = new pg.Client({ connectionString: urlOwner });
  await c.connect();
  const manifesto: { criadoEm: string; migracoes: string[]; tabelas: { nome: string; linhas: number; sha256: string }[] } = {
    criadoEm: new Date().toISOString(),
    migracoes: [],
    tabelas: [],
  };
  try {
    await c.query("begin isolation level repeatable read read only");
    manifesto.migracoes = (await c.query("select hash from drizzle.__drizzle_migrations order by id")).rows.map((r) => r.hash);
    for (const t of await tabelasOrdenadas(c)) {
      const dados = await lerTudo(c.query(copyTo(`copy "${t}" to stdout (format binary)`)));
      const linhas = Number((await c.query(`select count(*) from "${t}"`)).rows[0].count);
      writeFileSync(path.join(pasta, `${t}.bin.enc`), cifrar(dados, k));
      manifesto.tabelas.push({ nome: t, linhas, sha256: sha(dados) });
    }
    await c.query("commit");
  } finally {
    await c.end();
  }
  writeFileSync(path.join(pasta, "manifesto.json"), JSON.stringify(manifesto, null, 2));
  return { pasta, manifesto };
}

function urlCom(urlBase: string, usuario: string, senha: string, banco: string) {
  const u = new URL(urlBase);
  u.username = usuario;
  u.password = senha;
  u.pathname = `/${banco}`;
  return u.toString();
}

export async function restaurar(pasta: string) {
  const k = chave();
  const manifesto = JSON.parse(readFileSync(path.join(pasta, "manifesto.json"), "utf8")) as Awaited<ReturnType<typeof fazerBackup>>["manifesto"];
  const base = process.env.DATABASE_URL_OWNER!;
  const su = (banco: string) => urlCom(base, "postgres", process.env.PG_SUPERUSER_PASSWORD!, banco);

  const adm = new pg.Client({ connectionString: su("postgres") });
  await adm.connect();
  await adm.query(`drop database if exists ${BANCO_RESTAURACAO} with (force)`);
  await adm.query(`create database ${BANCO_RESTAURACAO} owner alta_owner`);
  await adm.query(`grant connect on database ${BANCO_RESTAURACAO} to alta_app`);
  await adm.end();

  // Esquema pelas migrações versionadas; depois os dados.
  await migrarBanco(urlCom(base, new URL(base).username, decodeURIComponent(new URL(base).password), BANCO_RESTAURACAO));

  const c = new pg.Client({ connectionString: su(BANCO_RESTAURACAO) });
  await c.connect();
  const resultado: { tabela: string; esperado: number; restaurado: number; integridade: boolean }[] = [];
  try {
    await c.query("begin");
    // Carga em massa: restrições checadas ao final por contagem e checksum.
    await c.query("set local session_replication_role = replica");
    for (const t of manifesto.tabelas) {
      const dados = decifrar(readFileSync(path.join(pasta, `${t.nome}.bin.enc`)), k);
      const integridade = sha(dados) === t.sha256;
      await c.query(`delete from "${t.nome}"`);
      await pipeline(Readable.from([dados]), c.query(copyFrom(`copy "${t.nome}" from stdin (format binary)`)));
      const restaurado = Number((await c.query(`select count(*) from "${t.nome}"`)).rows[0].count);
      resultado.push({ tabela: t.nome, esperado: t.linhas, restaurado, integridade });
    }
    // Ajusta sequências (bigserial da auditoria).
    await c.query(`select setval(pg_get_serial_sequence('auditoria', 'id'), coalesce(max(id), 1)) from auditoria`);
    // Pós-restauração (docs/implantacao.md): sessões e convites antigos não voltam a valer.
    await c.query("delete from session");
    await c.query("update convite set revogado_em = now() where consumido_em is null and revogado_em is null");
    await c.query("commit");
  } catch (e) {
    await c.query("rollback");
    throw e;
  } finally {
    await c.end();
  }
  return resultado;
}

async function main() {
  const [comando, arg] = process.argv.slice(2);
  if (comando === "backup") {
    const r = await fazerBackup(process.env.DATABASE_URL_OWNER!);
    console.log(`Backup em ${r.pasta}: ${r.manifesto.tabelas.length} tabelas.`);
  } else if (comando === "restaurar" && arg) {
    console.table(await restaurar(arg));
  } else if (comando === "teste") {
    const inicio = Date.now();
    const b = await fazerBackup(process.env.DATABASE_URL_OWNER!);
    const r = await restaurar(b.pasta);
    const ok = r.every((x) => x.integridade && x.esperado === x.restaurado);
    const evidencia = {
      executadoEm: new Date().toISOString(),
      resultado: ok ? "restauração conferida" : "DIVERGÊNCIA",
      duracaoMs: Date.now() - inicio,
      bancoRestaurado: BANCO_RESTAURACAO,
      tabelas: r,
      posRestauracao: ["sessões apagadas", "convites pendentes revogados"],
    };
    mkdirSync("docs/evidencias", { recursive: true });
    writeFileSync("docs/evidencias/backup-restauracao.json", JSON.stringify(evidencia, null, 2));
    console.table(r);
    console.log(ok ? `OK: restauração conferida em ${evidencia.duracaoMs} ms.` : "FALHA: há divergências.");
    process.exit(ok ? 0 : 1);
  } else {
    console.log("Uso: backup | restaurar <pasta> | teste");
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

// PostgreSQL local sem Docker, usando os binários oficiais empacotados pelo
// embedded-postgres. Quem tiver Docker pode usar docker-compose.yml no lugar.
//
//   npm run db        inicia o banco e mantém rodando (Ctrl+C para parar)
import { config } from "dotenv";
import EmbeddedPostgres from "embedded-postgres";
import { existsSync } from "node:fs";
import path from "node:path";
import pg from "pg";

config({ path: ".env.local", override: true });

function exigir(nome: string): string {
  const valor = process.env[nome];
  if (!valor) throw new Error(`${nome} ausente. Rode "npm run setup" primeiro.`);
  return valor;
}

const porta = Number(exigir("PG_PORT"));
const senhaSuper = exigir("PG_SUPERUSER_PASSWORD");
const diretorio = path.resolve(".pgdata");

const servidor = new EmbeddedPostgres({
  databaseDir: diretorio,
  port: porta,
  user: "postgres",
  password: senhaSuper,
  authMethod: "scram-sha-256",
  persistent: true,
  initdbFlags: ["--encoding=UTF8", "--locale=C"],
  onLog: () => {},
});

async function prepararPapeis() {
  const cliente = new pg.Client({
    host: "localhost",
    port: porta,
    user: "postgres",
    password: senhaSuper,
    database: "postgres",
  });
  await cliente.connect();
  try {
    // Senhas vêm do .env.local; format('%L') faz o escape correto do literal.
    for (const [papel, senha] of [
      ["alta_owner", exigir("DB_OWNER_PASSWORD")],
      ["alta_app", exigir("DB_APP_PASSWORD")],
    ]) {
      const { rows } = await cliente.query("select 1 from pg_roles where rolname = $1", [papel]);
      const comando = rows.length ? "alter" : "create";
      const { rows: sql } = await cliente.query(
        `select format('${comando} role %I with login nosuperuser nocreatedb nocreaterole nobypassrls password %L', $1::text, $2::text) as q`,
        [papel, senha],
      );
      await cliente.query(sql[0].q);
    }
    const { rows } = await cliente.query("select 1 from pg_database where datname = 'alta_clara'");
    if (!rows.length) await cliente.query("create database alta_clara owner alta_owner");
    await cliente.query("revoke all on database alta_clara from public");
    await cliente.query("grant connect on database alta_clara to alta_app");
  } finally {
    await cliente.end();
  }
}

async function main() {
  if (!existsSync(path.join(diretorio, "PG_VERSION"))) {
    console.log("Criando cluster PostgreSQL em .pgdata ...");
    await servidor.initialise();
  }
  await servidor.start();
  await prepararPapeis();
  console.log(`PostgreSQL rodando em localhost:${porta} (banco alta_clara). Ctrl+C para parar.`);

  const parar = async () => {
    await servidor.stop();
    process.exit(0);
  };
  process.on("SIGINT", parar);
  process.on("SIGTERM", parar);
  setInterval(() => {}, 1 << 30);
}

main().catch((erro) => {
  console.error(erro);
  process.exit(1);
});

// Teste de ponta a ponta no navegador real (Chrome instalado na máquina).
// Requer: `npm run db` e `npm run dev -- --port 3100` rodando.
// ATENÇÃO: recria os dados sintéticos de desenvolvimento (seed --reset).
//
//   npx tsx scripts/e2e.ts
import { execSync } from "node:child_process";
import { createHmac } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { config } from "dotenv";
import jsQR from "jsqr";
import pg from "pg";
import { chromium, type Page } from "playwright-core";
import { PNG } from "pngjs";

config({ path: ".env.local", override: true });

const BASE = process.env.E2E_URL ?? "http://localhost:3100";
const CHROME = process.env.CHROME_PATH ?? "C:/Program Files/Google/Chrome/Application/chrome.exe";
const SAIDA = "docs/evidencias";
mkdirSync(SAIDA, { recursive: true });

const resultados: { etapa: string; ok: boolean; detalhe?: string }[] = [];
function registrar(etapa: string, ok: boolean, detalhe?: string) {
  resultados.push({ etapa, ok, detalhe });
  console.log(`${ok ? "OK   " : "FALHA"} ${etapa}${detalhe ? ` — ${detalhe}` : ""}`);
}

/** TOTP (RFC 6238, SHA-1, 30 s, 6 dígitos) — faz o papel do aplicativo autenticador. */
function totp(segredoBase32: string, agora = Date.now()) {
  const alfabeto = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  let bits = "";
  for (const c of segredoBase32.replace(/=+$/, "").toUpperCase()) bits += alfabeto.indexOf(c).toString(2).padStart(5, "0");
  const chave = Buffer.from(bits.match(/.{8}/g)!.map((b) => parseInt(b, 2)));
  const contador = Buffer.alloc(8);
  contador.writeBigUInt64BE(BigInt(Math.floor(agora / 30_000)));
  const h = createHmac("sha1", chave).update(contador).digest();
  const o = h[h.length - 1] & 0xf;
  return String((h.readUInt32BE(o) & 0x7fffffff) % 1_000_000).padStart(6, "0");
}

function credenciais() {
  const texto = readFileSync(".dev-credenciais.md", "utf8");
  const mapa: Record<string, string> = {};
  for (const m of texto.matchAll(/\| [^|]+ \| ([^ |]+) \| `([^`]+)` \|/g)) mapa[m[1]] = m[2];
  return mapa;
}

async function entrar(page: Page, email: string, senha: string) {
  await page.goto(`${BASE}/entrar`);
  await page.getByLabel("E-mail").fill(email);
  await page.getByLabel("Senha", { exact: true }).fill(senha);
  await page.getByRole("button", { name: "Entrar", exact: true }).click();
}

async function configurarTotp(page: Page, senha: string) {
  await page.waitForURL(/\/conta\/seguranca/);
  await page.getByLabel("Senha atual").fill(senha);
  await page.getByRole("button", { name: "Configurar" }).click();
  const segredo = (await page.locator("code").first().textContent())!.trim();
  await page.getByLabel("Digite o código mostrado no aplicativo").fill(totp(segredo));
  await page.screenshot({ path: path.join(SAIDA, "02-configurar-segundo-fator.png"), fullPage: true });
  await page.getByRole("button", { name: "Ativar verificação em duas etapas" }).click();
  await page.waitForURL(/\/equipe$/);
  return segredo;
}

async function entrarComTotp(page: Page, email: string, senha: string, segredo: string) {
  await entrar(page, email, senha);
  await page.waitForURL(/\/entrar\/verificacao/);
  await page.getByLabel("Código do autenticador").fill(totp(segredo));
  await page.getByRole("button", { name: "Verificar" }).click();
  await page.waitForURL(/\/equipe$/);
}

async function lerQr(page: Page, nome: string) {
  const png = PNG.sync.read(await page.getByRole("img", { name: nome }).screenshot());
  return jsQR(new Uint8ClampedArray(png.data), png.width, png.height)?.data ?? "";
}

async function sair(page: Page) {
  await page.getByRole("button", { name: "Sair" }).click();
  await page.waitForURL(/\/entrar\?motivo=encerrada/);
}

async function auditarAcessibilidade(page: Page, nome: string) {
  const axe = readFileSync(require.resolve("axe-core/axe.min.js"), "utf8");
  await page.addScriptTag({ content: axe });
  const r = await page.evaluate(async () => {
    // @ts-expect-error axe é injetado na página
    const res = await window.axe.run(document, { runOnly: { type: "tag", values: ["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa"] } });
    return res.violations.map((v: { id: string; impact: string; nodes: unknown[] }) => ({ id: v.id, impacto: v.impact, ocorrencias: v.nodes.length }));
  });
  registrar(`acessibilidade automática (axe) em ${nome}`, r.length === 0, r.length ? JSON.stringify(r) : "sem violações WCAG A/AA detectadas");
  return r;
}

async function main() {
  console.log("Recriando dados sintéticos…");
  execSync("npm run db:seed -- --reset", { stdio: "ignore" });
  const cred = credenciais();
  const db = new pg.Pool({ connectionString: process.env.DATABASE_URL_OWNER });

  const navegador = await chromium.launch({ executablePath: CHROME, headless: true });
  const ctxEquipe = await navegador.newContext({ viewport: { width: 1280, height: 900 }, locale: "pt-BR", timezoneId: "America/Sao_Paulo" });
  const equipe = await ctxEquipe.newPage();
  equipe.setDefaultTimeout(60_000);

  try {
    // Tela de login e teclado
    await equipe.goto(`${BASE}/entrar`);
    await equipe.screenshot({ path: path.join(SAIDA, "01-entrar.png"), fullPage: true });
    await auditarAcessibilidade(equipe, "/entrar");
    const ordem: string[] = [];
    await equipe.locator("body").click({ position: { x: 5, y: 5 } });
    for (let i = 0; i < 12; i++) {
      await equipe.keyboard.press("Tab");
      ordem.push(await equipe.evaluate(() => {
        const el = document.activeElement as HTMLElement | null;
        return el ? `${el.tagName.toLowerCase()}:${el.getAttribute("aria-label") ?? el.id ?? ""}${el.textContent?.trim().slice(0, 20) ?? ""}` : "";
      }));
    }
    const alcancaFormulario = ordem.some((o) => o.startsWith("input:email")) && ordem.some((o) => o.startsWith("input:senha")) && ordem.some((o) => o.includes("Entrar"));
    registrar("login navegável por teclado (e-mail → senha → Entrar)", alcancaFormulario, ordem.join(" | "));

    // Enfermagem: primeiro acesso exige configurar o segundo fator
    await entrar(equipe, "ana.enfermagem@norte.exemplo.test", cred["ana.enfermagem@norte.exemplo.test"]);
    const segredoAna = await configurarTotp(equipe, cred["ana.enfermagem@norte.exemplo.test"]);
    registrar("profissional sem MFA é levado a configurar TOTP antes da área da equipe", true);

    await equipe.getByRole("link", { name: "Maria Exemplo da Silva" }).click();
    await equipe.getByRole("button", { name: "Criar rascunho" }).click();
    await equipe.waitForURL(/\/equipe\/planos\//);
    await equipe.getByRole("button", { name: "+ Adicionar medicamento" }).click();
    await equipe.getByLabel("Nome e concentração").fill("Medicamento demonstrativo E2E");
    await equipe.getByLabel("Para que serve (linguagem simples)").fill("Exemplo criado pelo teste de ponta a ponta.");
    await equipe.getByLabel("Dose").fill("1 comprimido (exemplo)");
    await equipe.getByRole("button", { name: "Salvar rascunho" }).click();
    await equipe.getByText("Rascunho salvo.").waitFor();
    await equipe.screenshot({ path: path.join(SAIDA, "03-editor-rascunho.png"), fullPage: true });
    await equipe.getByRole("button", { name: "Enviar para revisão" }).click();
    await equipe.getByText("Aguardando revisão").waitFor();
    registrar("enfermagem cria rascunho a partir de modelo, inclui medicamento e envia para revisão", true);
    await sair(equipe);

    // Revisor: aprova e publica (separação de funções)
    await entrar(equipe, "bruno.revisor@norte.exemplo.test", cred["bruno.revisor@norte.exemplo.test"]);
    await configurarTotp(equipe, cred["bruno.revisor@norte.exemplo.test"]);
    await auditarAcessibilidade(equipe, "/equipe");
    await equipe.getByRole("link", { name: "Maria Exemplo da Silva" }).click();
    await equipe.waitForURL(/\/equipe\/atendimentos\//);
    const urlAtendimento = equipe.url();
    await equipe.getByRole("link", { name: "Versão 1" }).click();
    await equipe.getByLabel(/Conferi o conteúdo/).check();
    await equipe.getByLabel("Digite o prontuário do paciente para confirmar").fill("N-000999");
    await equipe.getByRole("button", { name: "Aprovar e publicar" }).click();
    await equipe.getByText("O prontuário digitado não confere").waitFor();
    registrar("publicação recusada com prontuário de outro paciente", true);
    await equipe.getByLabel("Digite o prontuário do paciente para confirmar").fill("N-000101");
    await equipe.getByRole("button", { name: "Aprovar e publicar" }).click();
    await equipe.getByText("Publicado", { exact: true }).first().waitFor();
    await equipe.screenshot({ path: path.join(SAIDA, "04-publicado-previa.png"), fullPage: true });
    registrar("revisor diferente do autor aprova e publica", true);

    await equipe.goto(urlAtendimento);
    await equipe.getByRole("button", { name: "Gerar QR code de ativação" }).click();
    const qr = equipe.getByRole("img", { name: "QR code de ativação" });
    await qr.waitFor();
    await equipe.screenshot({ path: path.join(SAIDA, "05-qr-ativacao.png"), fullPage: true });
    const png = PNG.sync.read(await qr.screenshot());
    const lido = jsQR(new Uint8ClampedArray(png.data), png.width, png.height);
    const urlConvite = lido?.data ?? "";
    registrar("QR code contém só a URL de ativação com token no fragmento", /\/ativar#t=[A-Za-z0-9_-]{43}$/.test(urlConvite), urlConvite.replace(/#t=.*/, "#t=<token>"));
    await sair(equipe);

    // Paciente: ativação pelo QR code
    const ctxPaciente = await navegador.newContext({ viewport: { width: 390, height: 844 }, locale: "pt-BR", timezoneId: "America/Sao_Paulo", isMobile: true, hasTouch: true });
    const paciente = await ctxPaciente.newPage();
    paciente.setDefaultTimeout(60_000);
    const requisicoes: string[] = [];
    paciente.on("request", (r) => requisicoes.push(r.url()));
    await paciente.goto(urlConvite);
    await paciente.getByRole("button", { name: "Enviar código" }).waitFor();
    registrar("pré-visualização não mostra dados clínicos", !(await paciente.content()).includes("Medicamento demonstrativo"));
    registrar("token removido da barra de endereço", !paciente.url().includes("#t="), paciente.url());
    await paciente.screenshot({ path: path.join(SAIDA, "06-ativacao-previa.png"), fullPage: true });
    await paciente.getByRole("button", { name: "Enviar código" }).click();
    await paciente.getByLabel("Código recebido").waitFor();
    const { rows } = await db.query("select corpo from mensagem_dev where para = $1 order by criado_em desc limit 1", ["maria.paciente@exemplo.test"]);
    const codigo = rows[0].corpo.match(/\d{6}/)[0];
    await paciente.getByLabel("Código recebido").fill(codigo);
    await paciente.getByRole("button", { name: "Confirmar código" }).click();
    await paciente.getByLabel("Como prefere ser chamado?").fill("Maria");
    await paciente.getByLabel("Crie uma senha").fill("uma frase de teste bem comprida");
    await paciente.getByRole("button", { name: "Criar conta e ver minhas orientações" }).click();
    await paciente.waitForURL(/\/paciente$/);
