// Popula o banco com DADOS SINTÉTICOS: duas instituições fictícias, equipe em
// cada perfil, pacientes e modelos. Senhas aleatórias vão para
// .dev-credenciais.md (ignorado pelo git).
//
//   npm run db:seed            cria se o banco estiver vazio
//   npm run db:seed -- --reset apaga os dados e recria
import { config } from "dotenv";
import { randomBytes } from "node:crypto";
import { writeFileSync } from "node:fs";

config({ path: ".env.local", override: true });

async function main() {
  const { db, pool } = await import("../src/server/db/cliente");
  const s = await import("../src/server/db/schema");
  const { criarContaComSenha } = await import("../src/server/auth/contas");
  const { MODELOS_SINTETICOS } = await import("../src/server/dominio/dados-sinteticos");
  const { sql } = await import("drizzle-orm");

  if (process.argv.includes("--reset")) {
    const owner = new (await import("pg")).default.Pool({ connectionString: process.env.DATABASE_URL_OWNER });
    await owner.query(`truncate auditoria, lembrete, preferencia_lembrete, pendencia, confirmacao_entendimento, registro_dose, autorizacao_cuidador, convite, plano, modelo_protocolo,
      equipe_atendimento, atendimento, paciente, vinculo, instituicao, mensagem_dev,
      two_factor, passkey, session, account, verification, rate_limit, "user" restart identity cascade`);
    await owner.end();
    console.log("Dados apagados.");
  }

  const [{ n }] = await db.select({ n: sql<number>`count(*)::int` }).from(s.instituicao);
  if (n > 0) {
    console.log("O banco já tem dados. Use --reset para recriar.");
    await pool.end();
    return;
  }

  const credenciais: string[] = [];
  const senha = () => randomBytes(18).toString("base64url"); // 24 caracteres

  async function conta(email: string, nome: string) {
    const s1 = senha();
    const r = await criarContaComSenha({ email, nome, senha: s1 });
    if (!("userId" in r)) throw new Error(`Falha ao criar ${email}: ${r.erro}`);
    credenciais.push(`| ${nome} | ${email} | \`${s1}\` |`);
    return r.userId;
  }

  const hoje = new Intl.DateTimeFormat("en-CA", { timeZone: "America/Sao_Paulo" }).format(new Date());

  const instituicoes = [
    {
      nome: "Hospital Exemplo Norte (fictício)",
      dominio: "norte.exemplo.test",
      telefone: "(11) 0000-0001",
      equipe: [
        ["ana.enfermagem", "Ana Teste (Enfermagem)", "enfermagem"],
        ["bruno.revisor", "Bruno Teste (Revisor clínico)", "revisor"],
        ["carla.admin", "Carla Teste (Admin institucional)", "admin"],
        ["davi.auditor", "Davi Teste (Auditor)", "auditor"],
      ],
      pacientes: [
        { nome: "Maria Exemplo da Silva", nascimento: "1948-03-12", prontuario: "N-000101", email: "maria.paciente@exemplo.test", procedimento: "Cirurgia abdominal (exemplo)" },
        { nome: "João Fictício Souza", nascimento: "1975-11-02", prontuario: "N-000102", email: "joao.paciente@exemplo.test", procedimento: "Internação clínica (exemplo)" },
      ],
    },
    {
      nome: "Hospital Exemplo Sul (fictício)",
      dominio: "sul.exemplo.test",
      telefone: "(11) 0000-0002",
      equipe: [
        ["eva.enfermagem", "Eva Teste (Enfermagem)", "enfermagem"],
        ["fabio.revisor", "Fábio Teste (Revisor clínico)", "revisor"],
      ],
      pacientes: [
        { nome: "Helena Demonstração Lima", nascimento: "1960-07-21", prontuario: "S-000201", email: "helena.paciente@exemplo.test", procedimento: "Cirurgia abdominal (exemplo)" },
      ],
    },
  ] as const;

  for (const inst of instituicoes) {
    const [i] = await db.insert(s.instituicao).values({ nome: inst.nome, telefone: inst.telefone }).returning();
    const equipe: Record<string, string> = {};
    for (const [usuario, nome, papel] of inst.equipe as readonly (readonly [string, string, "enfermagem" | "revisor" | "admin" | "auditor"])[]) {
      const id = await conta(`${usuario}@${inst.dominio}`, nome);
      equipe[papel] = id;
      await db.insert(s.vinculo).values({ userId: id, instituicaoId: i.id, papel });
    }
    for (const m of MODELOS_SINTETICOS) {
      await db.insert(s.modeloProtocolo).values({ instituicaoId: i.id, nome: m.nome, versao: 1, conteudo: m.conteudo, sintetico: true });
    }
    for (const p of inst.pacientes) {
      const [pac] = await db
        .insert(s.paciente)
        .values({ instituicaoId: i.id, nome: p.nome, dataNascimento: p.nascimento, prontuario: p.prontuario, emailContato: p.email })
        .returning();
      const [at] = await db
        .insert(s.atendimento)
        .values({ instituicaoId: i.id, pacienteId: pac.id, procedimento: p.procedimento, unidade: "Clínica Cirúrgica — 3º andar (fictícia)", admissaoEm: hoje, altaPrevistaEm: hoje })
        .returning();
      await db.insert(s.equipeAtendimento).values({ atendimentoId: at.id, userId: equipe.enfermagem! });
    }
  }

  writeFileSync(
    ".dev-credenciais.md",
    `# Credenciais SINTÉTICAS de desenvolvimento\n\nGeradas em ${new Date().toISOString()}. Não use em outro ambiente.\n` +
      `Profissionais precisam configurar o segundo fator no primeiro acesso.\n` +
      `Pacientes são ativados pelo QR code gerado na área da equipe.\n\n| Nome | E-mail | Senha |\n|---|---|---|\n${credenciais.join("\n")}\n`,
    { mode: 0o600 },
  );
  console.log(`Dados sintéticos criados. Credenciais em .dev-credenciais.md (${credenciais.length} contas).`);
  await pool.end();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

"use client";

import Link from "next/link";
import { useEffect, useRef, useState, type FormEvent } from "react";
import { Aviso, Botao, Campo } from "@/components/ui";
import { concluirComSenhaAcao, verificarCodigoAcao, vincularContaAtualAcao } from "./acoes";

async function postarConvite(corpo: { token: string; acao: "previa" | "iniciar" }) {
  const r = await fetch("/ativar/iniciar", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(corpo),
    cache: "no-store",
  });
  return r.json();
}

type TipoConvite = "paciente" | "cuidador";

type Etapa =
  | { tipo: "lendo" }
  | { tipo: "sem_convite" }
  | { tipo: "erro"; estado: string }
  | { tipo: "previa"; instituicao: string; emailMascarado: string; convite: TipoConvite }
  | { tipo: "codigo"; instituicao: string; emailMascarado: string; convite: TipoConvite }
  | { tipo: "conta"; instituicao: string; emailMascarado: string; convite: TipoConvite };

const MENSAGENS_ESTADO: Record<string, string> = {
  expirado: "Este convite expirou. Peça um novo QR code à equipe da unidade. Suas orientações continuam guardadas.",
  revogado: "Este convite foi substituído por outro mais recente. Use o QR code mais novo que você recebeu.",
  usado: "Este convite já foi usado. Se a conta é sua, entre com seu e-mail e senha.",
  inexistente: "Não reconhecemos este QR code. Confira se a imagem está completa ou peça um novo à equipe.",
  aguarde: "Acabamos de enviar um código. Aguarde um minuto antes de pedir outro.",
};

export function Ativacao({
  andamento,
  contaLogada,
}: {
  andamento: { instituicao: string; emailMascarado: string; codigoVerificado: boolean; convite: TipoConvite } | null;
  contaLogada: boolean;
}) {
  const token = useRef<string | null>(null);
  const lido = useRef(false);
  const [etapa, setEtapa] = useState<Etapa>({ tipo: "lendo" });
  const [ocupado, setOcupado] = useState(false);

  useEffect(() => {
    // Executa uma única vez por montagem real (o modo estrito do React roda efeitos duas vezes em desenvolvimento).
    if (lido.current) return;
    lido.current = true;
    // O token vem no fragmento (#t=...), que o navegador não envia ao servidor.
    const fragmento = new URLSearchParams(window.location.hash.slice(1));
    const t = fragmento.get("t");
    if (t) {
      token.current = t;
      window.history.replaceState(window.history.state, "", "/ativar");
      postarConvite({ token: t, acao: "previa" }).then((r) =>
        setEtapa(
          r.estado === "valido"
            ? { tipo: "previa", instituicao: r.instituicao!, emailMascarado: r.emailMascarado!, convite: r.tipo }
            : { tipo: "erro", estado: r.estado },
        ),
      );
    } else if (andamento) {
      queueMicrotask(() =>
        setEtapa({ tipo: andamento.codigoVerificado ? "conta" : "codigo", instituicao: andamento.instituicao, emailMascarado: andamento.emailMascarado, convite: andamento.convite }),
      );
    } else {
      queueMicrotask(() => setEtapa({ tipo: "sem_convite" }));
    }
  }, [andamento]);

  async function continuar() {
    if (!token.current || etapa.tipo !== "previa") return;
    setOcupado(true);
    const r = await postarConvite({ token: token.current, acao: "iniciar" }).catch(() => ({ ok: false, erro: "inexistente" }));
    setOcupado(false);
    if (!r.ok) {
      setEtapa({ tipo: "erro", estado: r.erro });
      return;
    }
    token.current = null;
    setEtapa({ tipo: "codigo", instituicao: etapa.instituicao, emailMascarado: etapa.emailMascarado, convite: etapa.convite });
  }

  if (etapa.tipo === "lendo") return <p className="text-muted">Lendo o convite…</p>;

  if (etapa.tipo === "sem_convite") {
    return (
      <Aviso titulo="Abra pelo QR code">
        Para ativar o acesso, escaneie o QR code que a equipe entregou na sua alta. Já tem conta?{" "}
        <Link href="/entrar" className="font-semibold text-primary underline">
          Entrar
        </Link>
      </Aviso>
    );
  }

  if (etapa.tipo === "erro") {
    return (
      <Aviso tom="warn" titulo="Não foi possível continuar">
        {MENSAGENS_ESTADO[etapa.estado] ?? MENSAGENS_ESTADO.inexistente}
      </Aviso>
    );
  }

  return (
    <div className="space-y-6">
      <p className="rounded-xl bg-primary-soft p-4">
        {etapa.convite === "cuidador" ? (
          <>
            Convite para acompanhar, como <strong>cuidador</strong>, as orientações de um paciente de{" "}
            <strong>{etapa.instituicao}</strong>. Você terá a sua própria conta.
          </>
        ) : (
          <>
            Convite de <strong>{etapa.instituicao}</strong>.
          </>
        )}
      </p>

      {etapa.tipo === "previa" && (
        <>
          <p className="text-lg">
            Vamos enviar um código para <strong>{etapa.emailMascarado}</strong>
            {etapa.convite === "cuidador" ? ", o e-mail informado no convite." : ", o contato registrado no seu atendimento."}
            Nenhuma informação de saúde aparece antes dessa confirmação.
          </p>
          <Botao className="w-full" onClick={continuar} disabled={ocupado}>
            {ocupado ? "Enviando…" : "Enviar código"}
          </Botao>
          <p className="text-sm text-muted">
            Este não é o seu e-mail ou você não tem acesso a ele? A unidade pode fazer a ativação com você, com conferência
            de identidade.
          </p>
        </>
      )}

      {etapa.tipo === "codigo" && (
        <EtapaCodigo email={etapa.emailMascarado} onOk={() => setEtapa({ ...etapa, tipo: "conta" })} />
      )}

      {etapa.tipo === "conta" && <EtapaConta contaLogada={contaLogada} />}
    </div>
  );
}

function EtapaCodigo({ email, onOk }: { email: string; onOk: () => void }) {
  const [codigo, setCodigo] = useState("");
  const [erro, setErro] = useState<string | null>(null);
  const [ocupado, setOcupado] = useState(false);

  async function enviar(e: FormEvent) {
    e.preventDefault();
    setOcupado(true);
    setErro(null);
    const r = await verificarCodigoAcao(codigo);
    setOcupado(false);
    if (r.ok) return onOk();
    setErro(
      r.motivo === "tentativas"
        ? "Muitas tentativas. Escaneie o QR code de novo para receber outro código."
        : r.motivo === "expirado"
          ? "O código expirou. Escaneie o QR code de novo para receber outro."
          : r.motivo === "errado"
            ? `Código não confere. Tentativas restantes: ${"restantes" in r ? r.restantes : 0}.`
            : "Não foi possível verificar. Escaneie o QR code de novo.",
    );
  }

  return (
    <form onSubmit={enviar} className="space-y-4">
      <p>
        Enviamos um código de 6 números para <strong>{email}</strong>. Ele vale por 10 minutos.
      </p>
      <Campo
        id="codigo"
        rotulo="Código recebido"
        inputMode="numeric"
        autoComplete="one-time-code"
        autoFocus
        value={codigo}
        onChange={(e) => setCodigo(e.target.value)}
        erro={erro}
      />
      <Botao type="submit" className="w-full" disabled={ocupado || codigo.replace(/\D/g, "").length !== 6}>
        Confirmar código
      </Botao>
      {process.env.NODE_ENV !== "production" && (
        <p className="rounded-xl bg-warn-soft p-3 text-sm text-ink">
          Ambiente de desenvolvimento: as mensagens não saem da máquina. Veja o código em{" "}
          <a href="/dev/mensagens" target="_blank" className="font-semibold text-primary underline">
            /dev/mensagens
          </a>
          .
        </p>
      )}
    </form>
  );
}

function EtapaConta({ contaLogada }: { contaLogada: boolean }) {
  const [nome, setNome] = useState("");
  const [senha, setSenha] = useState("");
  const [mostrar, setMostrar] = useState(false);
  const [erro, setErro] = useState<string | null>(null);
  const [ocupado, setOcupado] = useState(false);

  async function criar(e: FormEvent) {
    e.preventDefault();
    setOcupado(true);
    setErro(null);
    const r = await concluirComSenhaAcao({ nome, senha });
    setOcupado(false);
    if (!r.ok) return setErro(r.erro);
    // Navegação completa de propósito: garante que o novo cookie de sessão valha em toda a página.
    // eslint-disable-next-line @next/next/no-location-assign-relative-destination
    window.location.assign("/paciente");
  }

  async function vincular() {
    setOcupado(true);
    const r = await vincularContaAtualAcao();
    setOcupado(false);
    if (!r.ok) return setErro(r.erro);
    // Navegação completa de propósito: garante que o novo cookie de sessão valha em toda a página.
    // eslint-disable-next-line @next/next/no-location-assign-relative-destination
    window.location.assign("/paciente");
  }

  return (
    <div className="space-y-6">
