            <label
              key={p.id}
              className="flex min-h-12 cursor-pointer items-center justify-center rounded-xl px-2 text-center text-sm font-bold text-primary has-checked:bg-surface has-checked:text-ink has-checked:shadow-sm has-focus-visible:outline-3 has-focus-visible:outline-(--focus)"
            >
              <input
                type="radio"
                name="perfil"
                value={p.id}
                checked={perfil === p.id}
                onChange={() => setPerfil(p.id)}
                className="sr-only"
              />
              {p.rotulo}
            </label>
          ))}
        </div>
        <p className="mt-2 text-sm text-muted" aria-live="polite">
          {dica}
        </p>
      </fieldset>

      {suportaPasskey ? (
        <div>
          <Botao variante="secundario" className="w-full" onClick={entrarComPasskey} disabled={enviando}>
            Entrar com passkey
          </Botao>
          <p className="mt-1.5 text-sm text-muted">
            Usa a biometria ou o PIN do seu aparelho. O Alta Clara não recebe sua digital nem seu rosto.
          </p>
        </div>
      ) : (
        <p className="rounded-xl bg-info-soft p-3 text-sm text-ink">
          Este navegador não oferece passkeys. Use e-mail e senha abaixo.
        </p>
      )}

      <div className="flex items-center gap-3 text-sm text-muted" aria-hidden="true">
        <span className="h-px flex-1 bg-line" /> ou <span className="h-px flex-1 bg-line" />
      </div>

      <form onSubmit={entrarComSenha} className="space-y-4" noValidate>
        <Campo
          id="email"
          rotulo="E-mail"
          type="email"
          autoComplete="username"
          inputMode="email"
          required
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        <Campo
          id="senha"
          rotulo="Senha"
          type={mostrarSenha ? "text" : "password"}
          autoComplete="current-password"
          required
          value={senha}
          onChange={(e) => setSenha(e.target.value)}
          acessorio={
            <button
              type="button"
              onClick={() => setMostrarSenha((v) => !v)}
              aria-pressed={mostrarSenha}
              aria-controls="senha"
              className="min-h-12 shrink-0 rounded-xl border-2 border-line px-3 text-sm font-bold text-primary"
            >
              {mostrarSenha ? "Ocultar" : "Mostrar"}
            </button>
          }
        />
        {erro && (
          <p role="alert" className="rounded-xl bg-danger-soft p-3 font-semibold text-danger">
            {erro}
          </p>
        )}
        <Botao type="submit" className="w-full" disabled={enviando}>
          {enviando ? "Entrando…" : "Entrar"}
        </Botao>
      </form>

      <p>
        <Link href="/entrar/recuperar" className="font-semibold text-primary underline underline-offset-4">
