export function EditorPlano({
  planoId,
  revisaoInicial,
  conteudoInicial,
  iaDisponivel,
}: {
  planoId: string;
  revisaoInicial: number;
  conteudoInicial: ConteudoPlano;
  iaDisponivel: boolean;
}) {
  const router = useRouter();
  const [c, setC] = useState<ConteudoPlano>(conteudoInicial);
  const [revisao, setRevisao] = useState(revisaoInicial);
  const [sujo, setSujo] = useState(false);
  const [mensagem, setMensagem] = useState<{ tom: "info" | "danger"; texto: string } | null>(null);
  const [ocupado, setOcupado] = useState(false);

  function alterar(f: (atual: ConteudoPlano) => ConteudoPlano) {
    setC((atual) => f(structuredClone(atual)));
    setSujo(true);
  }

  async function salvar(): Promise<number | null> {
    setOcupado(true);
    setMensagem(null);
    const r = await salvarRascunhoAcao(planoId, revisao, c);
    setOcupado(false);
    if (!r.ok) {
      setMensagem({ tom: "danger", texto: r.erro });
      return null;
    }
    setRevisao(r.revisao);
    setSujo(false);
    setMensagem({ tom: "info", texto: "Rascunho salvo." });
    return r.revisao;
  }

  async function enviar() {
    const nova = sujo ? await salvar() : revisao;
    if (nova === null) return;
    setOcupado(true);
    const r = await enviarRevisaoAcao(planoId, nova);
    setOcupado(false);
    if (!r.ok) return setMensagem({ tom: "danger", texto: r.erro });
    router.refresh();
  }

  return (
    <div className="space-y-6">
      <Aviso tom="warn" titulo="Organização das orientações, não prescrição">
        Transcreva os medicamentos da prescrição revisada. Alterar medicamento ou dose exige a autorização clínica
        correspondente. Este formulário não emite prescrição.
      </Aviso>

      <Bloco titulo="Dados gerais">
        <div className="grid gap-4 sm:grid-cols-2">
          <Rotulo texto="Primeiro dia em casa">
            <input type="date" className={entrada} value={c.inicio} onChange={(e) => alterar((x) => ({ ...x, inicio: e.target.value }))} />
          </Rotulo>
          <Rotulo texto="Equipe responsável">
            <input className={entrada} value={c.equipeResponsavel} onChange={(e) => alterar((x) => ({ ...x, equipeResponsavel: e.target.value }))} />
          </Rotulo>
          <Rotulo texto="Unidade para contato">
            <input className={entrada} value={c.contato.unidade} onChange={(e) => alterar((x) => ({ ...x, contato: { ...x.contato, unidade: e.target.value } }))} />
          </Rotulo>
          <Rotulo texto="Telefone da unidade">
            <input className={entrada} inputMode="tel" value={c.contato.telefone} onChange={(e) => alterar((x) => ({ ...x, contato: { ...x.contato, telefone: e.target.value } }))} />
          </Rotulo>
          <Rotulo texto="Horário de atendimento" largo>
            <input className={entrada} value={c.contato.horarioAtendimento} onChange={(e) => alterar((x) => ({ ...x, contato: { ...x.contato, horarioAtendimento: e.target.value } }))} />
          </Rotulo>
        </div>
      </Bloco>

      <Bloco titulo={`Medicamentos (${c.medicamentos.length})`}>
        <div className="space-y-5">
          {c.medicamentos.map((m, i) => (
            <fieldset key={m.id} className="rounded-xl border-2 border-line p-4">
              <legend className="px-2 font-bold">Medicamento {i + 1}</legend>
              <div className="grid gap-3 sm:grid-cols-2">
                <Rotulo texto="Nome e concentração">
                  <input className={entrada} value={m.nome} onChange={(e) => alterar((x) => ((x.medicamentos[i].nome = e.target.value), x))} />
                </Rotulo>
                <Rotulo texto="Para que serve (linguagem simples)">
                  <input className={entrada} value={m.finalidade} onChange={(e) => alterar((x) => ((x.medicamentos[i].finalidade = e.target.value), x))} />
                </Rotulo>
                <Rotulo texto="Forma">
                  <select className={entrada} value={m.apresentacao} onChange={(e) => alterar((x) => ((x.medicamentos[i].apresentacao = e.target.value as MedicamentoPlano["apresentacao"]), x))}>
                    {apresentacoes.map((a) => (
                      <option key={a} value={a}>
                        {ROTULO_APRESENTACAO[a]}
                      </option>
                    ))}
                  </select>
                </Rotulo>
                <Rotulo texto="Dose">
                  <input className={entrada} value={m.dose} onChange={(e) => alterar((x) => ((x.medicamentos[i].dose = e.target.value), x))} />
                </Rotulo>
                <Rotulo texto="Via / como usar">
                  <input className={entrada} value={m.via} onChange={(e) => alterar((x) => ((x.medicamentos[i].via = e.target.value), x))} />
                </Rotulo>
                <Rotulo texto="Duração (dias)">
                  <div className="flex items-center gap-3">
                    <input
                      type="number"
                      min={1}
                      max={365}
                      className={entrada}
                      disabled={m.duracaoDias === null}
                      value={m.duracaoDias ?? ""}
                      onChange={(e) => alterar((x) => ((x.medicamentos[i].duracaoDias = Number(e.target.value) || 1), x))}
                    />
                    <label className="flex shrink-0 items-center gap-2 text-sm">
                      <input type="checkbox" checked={m.duracaoDias === null} onChange={(e) => alterar((x) => ((x.medicamentos[i].duracaoDias = e.target.checked ? null : 7), x))} />
                      Contínuo
                    </label>
                  </div>
                </Rotulo>
              </div>

              <div className="mt-4 space-y-3">
                <p className="font-bold">Regime</p>
                <div className="flex flex-wrap gap-4">
                  <label className="flex items-center gap-2">
                    <input
                      type="radio"
                      name={`regime-${m.id}`}
                      checked={!m.seNecessario}
                      onChange={() => alterar((x) => ((x.medicamentos[i] = { ...x.medicamentos[i], seNecessario: null, horarios: ["08:00"] }), x))}
                    />
                    Horários fixos
                  </label>
                  <label className="flex items-center gap-2">
                    <input
                      type="radio"
                      name={`regime-${m.id}`}
                      checked={Boolean(m.seNecessario)}
                      onChange={() =>
                        alterar((x) => ((x.medicamentos[i] = { ...x.medicamentos[i], horarios: [], seNecessario: { quando: "", intervaloMinimoHoras: 6, maximoPorDia: 4 } }), x))
                      }
                    />
                    Somente se necessário
                  </label>
                </div>
                {m.seNecessario ? (
                  <div className="grid gap-3 sm:grid-cols-3">
                    <Rotulo texto="Quando usar">
                      <input className={entrada} value={m.seNecessario.quando} onChange={(e) => alterar((x) => ((x.medicamentos[i].seNecessario!.quando = e.target.value), x))} />
                    </Rotulo>
                    <Rotulo texto="Intervalo mínimo (h)">
                      <input type="number" min={1} max={48} className={entrada} value={m.seNecessario.intervaloMinimoHoras} onChange={(e) => alterar((x) => ((x.medicamentos[i].seNecessario!.intervaloMinimoHoras = Number(e.target.value)), x))} />
                    </Rotulo>
                    <Rotulo texto="Máximo por dia">
                      <input type="number" min={1} max={12} className={entrada} value={m.seNecessario.maximoPorDia} onChange={(e) => alterar((x) => ((x.medicamentos[i].seNecessario!.maximoPorDia = Number(e.target.value)), x))} />
                    </Rotulo>
                  </div>
                ) : (
                  <div className="flex flex-wrap items-end gap-2">
                    {m.horarios.map((h, j) => (
                      <span key={j} className="flex items-center gap-1">
                        <input
                          type="time"
                          aria-label={`Horário ${j + 1}`}
                          className="min-h-11 rounded-lg border-2 border-line bg-surface px-2"
                          value={h}
                          onChange={(e) => alterar((x) => ((x.medicamentos[i].horarios[j] = e.target.value), x))}
                        />
                        <button type="button" aria-label={`Remover horário ${j + 1}`} className="min-h-11 min-w-11 rounded-lg text-danger" onClick={() => alterar((x) => (x.medicamentos[i].horarios.splice(j, 1), x))}>
                          ×
                        </button>
                      </span>
                    ))}
                    <Botao variante="discreto" onClick={() => alterar((x) => (x.medicamentos[i].horarios.push("12:00"), x))}>
                      + horário
                    </Botao>
                  </div>
                )}
              </div>

              <div className="mt-4">
                <Rotulo texto="Observação para o paciente (opcional)">
                  <input className={entrada} value={m.observacao ?? ""} onChange={(e) => alterar((x) => ((x.medicamentos[i].observacao = e.target.value || null), x))} />
                </Rotulo>
              </div>
              <Botao variante="discreto" className="mt-2 px-0 text-danger" onClick={() => alterar((x) => (x.medicamentos.splice(i, 1), x))}>
                Remover medicamento
              </Botao>
            </fieldset>
          ))}
          <Botao variante="secundario" onClick={() => alterar((x) => (x.medicamentos.push(novoMedicamento()), x))}>
            + Adicionar medicamento
          </Botao>
        </div>
      </Bloco>

      <Bloco titulo="Cuidados em casa">
        <div className="space-y-3">
          {c.cuidados.map((cu, i) => (
            <div key={i} className="grid gap-2 rounded-xl border border-line p-3 sm:grid-cols-[10rem_1fr_auto]">
              <select aria-label="Categoria" className={entrada} value={cu.categoria} onChange={(e) => alterar((x) => ((x.cuidados[i].categoria = e.target.value as typeof cu.categoria), x))}>
                {categoriasCuidado.map((k) => (
                  <option key={k} value={k}>
                    {ROTULO_CATEGORIA[k]}
                  </option>
                ))}
              </select>
              <div className="space-y-2">
                <input aria-label="Título" className={entrada} value={cu.titulo} onChange={(e) => alterar((x) => ((x.cuidados[i].titulo = e.target.value), x))} />
                <textarea aria-label="Orientação" rows={2} className={`${entrada} py-2`} value={cu.texto} onChange={(e) => alterar((x) => ((x.cuidados[i].texto = e.target.value), x))} />
                <SimplificarIA texto={cu.texto} disponivel={iaDisponivel} onAceitar={(novo) => alterar((x) => ((x.cuidados[i].texto = novo), x))} />
              </div>
              <button type="button" className="min-h-11 rounded-lg px-3 text-danger underline" onClick={() => alterar((x) => (x.cuidados.splice(i, 1), x))}>
                Remover
              </button>
            </div>
          ))}
          <Botao variante="secundario" onClick={() => alterar((x) => (x.cuidados.push({ categoria: "outro", titulo: "", texto: "" }), x))}>
            + Adicionar cuidado
          </Botao>
        </div>
      </Bloco>

      <Bloco titulo="Quando procurar ajuda">
        <p className="mb-3 text-sm text-muted">
          O conteúdo deve vir de protocolo aprovado e individualização profissional. Inclua ao menos uma orientação de urgência.
        </p>
        <div className="space-y-5">
          {niveisSinal.map((nivel) => (
            <div key={nivel}>
              <p className="font-bold">{ROTULO_NIVEL[nivel]}</p>
              <ul className="mt-2 space-y-2">
                {c.sinais.map((s, i) =>
                  s.nivel !== nivel ? null : (
                    <li key={i} className="flex gap-2">
                      <input aria-label={`${ROTULO_NIVEL[nivel]}: item`} className={entrada} value={s.texto} onChange={(e) => alterar((x) => ((x.sinais[i].texto = e.target.value), x))} />
                      <button type="button" aria-label="Remover item" className="min-h-11 min-w-11 rounded-lg text-danger" onClick={() => alterar((x) => (x.sinais.splice(i, 1), x))}>
                        ×
                      </button>
                    </li>
                  ),
                )}
              </ul>
              <Botao variante="discreto" className="px-0" onClick={() => alterar((x) => (x.sinais.push({ nivel, texto: "" }), x))}>
                + item
              </Botao>
            </div>
          ))}
        </div>
      </Bloco>

      <Bloco titulo="Retornos">
        <div className="space-y-3">
          {c.retornos.map((r, i) => (
            <div key={i} className="grid gap-3 rounded-xl border border-line p-3 sm:grid-cols-2">
              <Rotulo texto="Local">
                <input className={entrada} value={r.local} onChange={(e) => alterar((x) => ((x.retornos[i].local = e.target.value), x))} />
              </Rotulo>
              <Rotulo texto="Data e hora (vazio = ainda não agendado)">
                <input type="datetime-local" className={entrada} value={r.dataHora ?? ""} onChange={(e) => alterar((x) => ((x.retornos[i].dataHora = e.target.value || null), x))} />
              </Rotulo>
              <Rotulo texto="O que levar (separe por vírgula)" largo>
                <input
                  className={entrada}
                  value={r.levar.join(", ")}
                  onChange={(e) => alterar((x) => ((x.retornos[i].levar = e.target.value.split(",").map((v) => v.trim()).filter(Boolean)), x))}
                />
              </Rotulo>
              <button type="button" className="justify-self-start text-danger underline" onClick={() => alterar((x) => (x.retornos.splice(i, 1), x))}>
                Remover retorno
              </button>
            </div>
          ))}
          <Botao variante="secundario" onClick={() => alterar((x) => (x.retornos.push({ local: c.contato.unidade, dataHora: null, levar: [] }), x))}>
            + Adicionar retorno
          </Botao>
        </div>
      </Bloco>

      <div className="sticky bottom-0 z-10 -mx-4 border-t border-line bg-bg/95 px-4 py-3 backdrop-blur">
        {mensagem && (
          <p role={mensagem.tom === "danger" ? "alert" : "status"} className={`mb-2 font-semibold ${mensagem.tom === "danger" ? "text-danger" : "text-primary"}`}>
            {mensagem.texto}
          </p>
        )}
        <div className="flex flex-wrap items-center gap-3">
          <Botao onClick={salvar} disabled={ocupado || !sujo}>
            Salvar rascunho
          </Botao>
          <Botao variante="secundario" onClick={enviar} disabled={ocupado}>
            Enviar para revisão
          </Botao>
          <span className="text-sm text-muted">{sujo ? "Há alterações não salvas." : "Tudo salvo."}</span>
        </div>
      </div>
    </div>
  );
}

function Bloco({ titulo, children }: { titulo: string; children: ReactNode }) {
  return (
    <Cartao>
      <h2 className="mb-4 text-xl font-extrabold">{titulo}</h2>
      {children}
    </Cartao>
  );
}

function Rotulo({ texto, children, largo }: { texto: string; children: ReactNode; largo?: boolean }) {
  return (
    <label className={`block ${largo ? "sm:col-span-2" : ""}`}>
      <span className="mb-1 block text-sm font-bold">{texto}</span>
      {children}
    </label>
  );
}

"use client";

import QRCode from "qrcode";
import { useRouter } from "next/navigation";
import { useState, type FormEvent } from "react";
import { Aviso, Botao, Campo, Cartao } from "@/components/ui";
import { cancelarConviteAcao, convidarCuidadorAcao, revogarCuidadorAcao } from "./acoes";

const ROTULO_ESCOPO: Record<string, string> = {
  ver_plano: "Ver as orientações",
  registrar_dose: "Registrar remédios tomados",
};

const dataCurta = (iso: string) => new Date(iso).toLocaleDateString("pt-BR");

export function GestaoCuidadores({
  pacienteId,
  instituicao,
  mostrarInstituicao,
  ativos,
  pendentes,
}: {
  pacienteId: string;
  instituicao: string;
  mostrarInstituicao: boolean;
  ativos: { id: string; nome: string; email: string; escopo: string[]; desde: string; expiraEm: string | null }[];
  pendentes: { id: string; apelido: string | null; email: string; escopo: string[] | null; expiraEm: string }[];
}) {
  const router = useRouter();
  const [apelido, setApelido] = useState("");
  const [email, setEmail] = useState("");
  const [registrar, setRegistrar] = useState(false);
  const [validade, setValidade] = useState<"30" | "90" | "365" | "sem">("90");
  const [erro, setErro] = useState<string | null>(null);
  const [convite, setConvite] = useState<{ svg: string; url: string; email: string } | null>(null);
  const [copiado, setCopiado] = useState(false);

  async function convidar(e: FormEvent) {
    e.preventDefault();
    setErro(null);
    const r = await convidarCuidadorAcao({
      pacienteId,
      apelido,
      email,
      escopo: registrar ? ["ver_plano", "registrar_dose"] : ["ver_plano"],
      validadeDias: validade === "sem" ? null : Number(validade),
    });
    if (!r.ok) return setErro(r.erro);
    const url = `${window.location.origin}/ativar#t=${r.token}`;
    setConvite({ url, email: r.emailMascarado, svg: await QRCode.toString(url, { type: "svg", margin: 1 }) });
    setApelido("");
    setEmail("");
    router.refresh();
  }

  async function revogar(id: string, nome: string) {
    if (!window.confirm(`Encerrar o acesso de ${nome}? A pessoa deixa de ver suas orientações imediatamente.`)) return;
    const r = await revogarCuidadorAcao(id);
    if (!r.ok) return setErro(r.erro);
    router.refresh();
  }

  async function cancelar(id: string) {
    const r = await cancelarConviteAcao(id);
    if (!r.ok) return setErro(r.erro);
    router.refresh();
  }

  return (
    <div className="mt-6 space-y-6">
      {mostrarInstituicao && <h2 className="text-xl font-extrabold">{instituicao}</h2>}
      {erro && <Aviso tom="danger">{erro}</Aviso>}

      <Cartao>
        <h2 className="text-xl font-extrabold">Pessoas com acesso</h2>
        {ativos.length === 0 ? (
          <p className="mt-2 text-muted">Ninguém além de você.</p>
        ) : (
          <ul className="mt-3 divide-y divide-line">
            {ativos.map((a) => (
              <li key={a.id} className="flex flex-wrap items-center justify-between gap-3 py-3">
                <div>
                  <p className="font-bold">{a.nome}</p>
                  <p className="text-sm text-muted">{a.escopo.map((e) => ROTULO_ESCOPO[e] ?? e).join(" · ")}</p>
                  <p className="text-sm text-muted">
                    Desde {dataCurta(a.desde)} · {a.expiraEm ? `até ${dataCurta(a.expiraEm)}` : "até você encerrar"}
                  </p>
                </div>
                <Botao variante="perigo" onClick={() => revogar(a.id, a.nome)}>
                  Encerrar acesso
                </Botao>
              </li>
            ))}
          </ul>
        )}
        {pendentes.length > 0 && (
          <>
            <h3 className="mt-5 font-bold">Convites aguardando</h3>
            <ul className="mt-2 divide-y divide-line">
              {pendentes.map((p) => (
                <li key={p.id} className="flex flex-wrap items-center justify-between gap-3 py-2">
                  <span>
                    {p.apelido} · {p.email}
                    <span className="block text-sm text-muted">Vale até {dataCurta(p.expiraEm)}</span>
                  </span>
                  <Botao variante="discreto" onClick={() => cancelar(p.id)}>
                    Cancelar convite
                  </Botao>
                </li>
              ))}
            </ul>
          </>
        )}
      </Cartao>

      {convite ? (
        <Cartao className="border-2 border-primary">
          <h2 className="text-xl font-extrabold">Convite criado</h2>
          <p className="mt-1">
            Mostre o QR code ou envie o link para a pessoa. Ela vai receber um código de confirmação em <strong>{convite.email}</strong>.
          </p>
          <div className="mt-4 size-52 rounded-xl bg-white p-2" role="img" aria-label="QR code do convite de cuidador" dangerouslySetInnerHTML={{ __html: convite.svg }} />
          <div className="mt-3 flex flex-wrap gap-2">
            <Botao
              variante="secundario"
              onClick={async () => {
                await navigator.clipboard.writeText(convite.url);
                setCopiado(true);
              }}
            >
              {copiado ? "Link copiado" : "Copiar link"}
            </Botao>
            <Botao variante="discreto" onClick={() => setConvite(null)}>
              Fechar
            </Botao>
          </div>
          <p className="mt-2 text-sm text-muted">O convite vale por 72 horas e só funciona uma vez.</p>
        </Cartao>
      ) : (
        <Cartao>
          <h2 className="text-xl font-extrabold">Convidar alguém</h2>
          <form onSubmit={convidar} className="mt-3 space-y-4">
            <Campo id={`apelido-${pacienteId}`} rotulo="Quem é" dica="Ex.: Filha Ana, Vizinho João" value={apelido} onChange={(e) => setApelido(e.target.value)} />
            <Campo id={`email-${pacienteId}`} rotulo="E-mail da pessoa" type="email" autoComplete="off" value={email} onChange={(e) => setEmail(e.target.value)} />
            <fieldset>
              <legend className="font-bold">O que a pessoa pode fazer</legend>
              <label className="mt-2 flex items-center gap-3">
                <input type="checkbox" checked disabled className="size-5" /> Ver as orientações
              </label>
              <label className="mt-2 flex items-center gap-3">
                <input type="checkbox" checked={registrar} onChange={(e) => setRegistrar(e.target.checked)} className="size-5" />
                Registrar remédios tomados por mim
              </label>
            </fieldset>
            <div>
              <label htmlFor={`validade-${pacienteId}`} className="font-bold">
                Por quanto tempo
              </label>
              <select
                id={`validade-${pacienteId}`}
                value={validade}
                onChange={(e) => setValidade(e.target.value as typeof validade)}
                className="mt-1 min-h-12 w-full rounded-xl border-2 border-line bg-surface px-3"
              >
                <option value="30">30 dias</option>
                <option value="90">90 dias</option>
                <option value="365">1 ano</option>
                <option value="sem">Até eu encerrar</option>
              </select>
            </div>
            <Botao type="submit" disabled={apelido.trim().length < 2 || !email.includes("@")}>
              Criar convite
            </Botao>
          </form>
        </Cartao>
      )}
    </div>
  );
}

"use client";

import Link from "next/link";
import { useState, type FormEvent } from "react";
import { Aviso, Botao } from "@/components/ui";
import { responderEntendimentoAcao } from "../../../acoes";

type Pergunta = { id: string; enunciado: string; opcoes: { id: string; texto: string }[]; secao: string };
type Resultado = { acertos: number; total: number; resultado: { id: string; enunciado: string; secao: string; correta: boolean; respostaCerta: string }[] };

const SECAO = { remedios: "Seus remédios", ajuda: "Quando procurar ajuda" } as Record<string, string>;

/** Uma pergunta por vez (modo de simplicidade), com resposta corrigida no servidor. */
export function Questionario({ planoId, perguntas }: { planoId: string; perguntas: Pergunta[] }) {
  const [indice, setIndice] = useState(0);
  const [respostas, setRespostas] = useState<Record<string, string>>({});
  const [resultado, setResultado] = useState<Resultado | null>(null);
  const [erro, setErro] = useState(false);
  const atual = perguntas[indice];

  async function avancar(e: FormEvent) {
    e.preventDefault();
    if (indice < perguntas.length - 1) return setIndice(indice + 1);
    const r = await responderEntendimentoAcao(planoId, respostas);
    if (!r.ok) return setErro(true);
    setResultado(r);
  }

  if (resultado) {
    return (
      <div className="mt-6 space-y-4" role="status">
        <p className="text-xl font-bold">
          Você respondeu {resultado.total} perguntas. {resultado.acertos === resultado.total ? "Tudo de acordo com o plano." : "Alguns pontos merecem reforço."}
        </p>
        <ul className="space-y-3">
          {resultado.resultado.map((r) => (
            <li key={r.id} className={`rounded-2xl border-2 p-4 ${r.correta ? "border-primary bg-primary-soft" : "border-warn bg-warn-soft"}`}>
              <p className="font-semibold text-ink">{r.enunciado}</p>
              <p className="mt-1 text-ink">
                {r.correta ? "De acordo com o plano." : "Segundo o seu plano:"} <strong>{r.respostaCerta}</strong>
              </p>
              {!r.correta && <p className="mt-1 text-sm text-ink">Veja em “{SECAO[r.secao]}”. A equipe foi avisada para reforçar este ponto com você.</p>}
            </li>
          ))}
        </ul>
        <p className="text-muted">Acertar estas perguntas não substitui conversar com a equipe sempre que tiver dúvida.</p>
        <Link href={`/paciente/planos/${planoId}`} className="inline-block font-semibold text-primary underline">
          Voltar ao plano
        </Link>
      </div>
    );
  }

  return (
    <form onSubmit={avancar} className="mt-6 space-y-5">
      <p className="text-sm font-bold text-muted" aria-live="polite">
        Pergunta {indice + 1} de {perguntas.length}
      </p>
      <fieldset key={atual.id}>
        <legend className="text-xl font-bold">{atual.enunciado}</legend>
        <div className="mt-4 space-y-2">
          {atual.opcoes.map((o) => (
            <label key={o.id} className="flex min-h-14 cursor-pointer items-center gap-3 rounded-xl border-2 border-line bg-surface px-4 has-checked:border-primary has-checked:bg-primary-soft">
              <input
                type="radio"
                name={atual.id}
                value={o.id}
                checked={respostas[atual.id] === o.id}
                onChange={() => setRespostas({ ...respostas, [atual.id]: o.id })}
                className="size-5"
              />
              <span className="text-lg">{o.texto}</span>
            </label>
          ))}
        </div>
      </fieldset>
      {erro && <Aviso tom="danger">Não foi possível enviar. Tente de novo.</Aviso>}
      <div className="flex gap-3">
        {indice > 0 && (
          <Botao variante="secundario" onClick={() => setIndice(indice - 1)}>
            Voltar
          </Botao>
        )}
        <Botao type="submit" disabled={!respostas[atual.id]}>
          {indice < perguntas.length - 1 ? "Próxima" : "Ver resultado"}
        </Botao>
      </div>
    </form>
  );
}

