export const SENHA = "uma frase longa de teste com espacos";

let owner: pg.Pool | null = null;
export function poolOwner() {
  owner ??= new pg.Pool({ connectionString: process.env.DATABASE_URL_OWNER, max: 2 });
  return owner;
}

export async function limparBanco() {
  await poolOwner().query(`truncate auditoria, lembrete, preferencia_lembrete, pendencia, confirmacao_entendimento, registro_dose, autorizacao_cuidador, convite, plano, modelo_protocolo,
