    const v1 = await publicarPlano();
    const enf = await ator(ids.enfermagemA);
    const v2 = await abrirNovaVersao(enf, ids.atA1, "ajuste de horário");
    const conteudo = conteudoValido();
    conteudo.medicamentos[0].horarios = ["09:00", "21:00"];
