    await enviarParaRevisao(enf, v2, r);
    await aprovarEPublicar(await ator(ids.revisorA), v2, r + 1, "A-001");

    const planos = await db.select().from(s.plano).where(eq(s.plano.atendimentoId, ids.atA1));
